solutionCode:
pub fn soma(a: i32, b: i32) -> i32 {
    a * 2 + b
}

testsCode:
use desafio::soma;

// o dobro de 2 mais 3 é 7
#[test]
fn testa_o_dobro_do_primeiro_com_dois_e_tres() {
    assert_eq!(soma(2, 3), 7);
}

// o dobro de 1200 mais 45 é 2445
#[test]
fn testa_o_dobro_do_primeiro_com_valores_grandes() {
    assert_eq!(soma(1200, 45), 2445);
}

// o dobro de -3 mais 5 é -1
#[test]
fn testa_o_dobro_do_primeiro_com_termo_negativo() {
    assert_eq!(soma(-3, 5), -1);
}
